action.command:
node -e "
const d = JSON.parse(require('fs').readFileSync('.devcontainer/keycloak/imports/startuphafen.json','utf8'));
console.log('loginTheme:', d.loginTheme);
console.log('clients:', d.clients.map(c => c.clientId));
console.log('roles:', d.roles && d.roles.realm && d.roles.realm.map(r=>r.name));
const u = d.users.find(x=>x.username==='alice');
console.log('alice enabled:', u.enabled, 'emailVerified:', u.emailVerified);
console.log('smtp:', JSON.stringify(d.smtpServer));
"

